#include "physics_library.hpp"

#include <SDL3/SDL.h>
#include <string>

namespace bb::gfx {
	SDL_SharedObject* open_codec_file(const std::string& path); // graphics_dds.cpp: by full path, on Windows without the current directory and PATH.
}

namespace bb::physics {
namespace {
	api  functions = {};
	bool tried = false, loaded = false;

	SDL_SharedObject* open_file(const std::string& file)
	{
		if (const char* base = SDL_GetBasePath()) {
			if (SDL_SharedObject* object = bb::gfx::open_codec_file(std::string(base) + file)) {
				return object;
			}
		}
		return nullptr;
	}
} // namespace

api const* library()
{
	if (tried) {
		return loaded ? &functions : nullptr;
	}
	tried = true;
	static const char* const names[] = { "libblitzphysics.so", "libblitzphysics.dylib", "blitzphysics.dll" };
	SDL_SharedObject*        object  = nullptr;
	for (const char* name : names) {
		if ((object = open_file(name)) != nullptr) {
			break;
		}
	}
	if (!object) {
		return nullptr;
	}
	auto version = reinterpret_cast<decltype(&::bp_version)>(SDL_LoadFunction(object, "bp_version"));
	if (!version || (version() != BP_VERSION)) {
		return nullptr;
	}
#define BB_BP(name) functions.name = reinterpret_cast<decltype(functions.name)>(SDL_LoadFunction(object, "bp_" #name))
	BB_BP(world_create);
	BB_BP(world_destroy);
	BB_BP(mesh_create);
	BB_BP(mesh_destroy);
	BB_BP(mesh_query_box);
	BB_BP(body_add_mesh);
	BB_BP(body_remove);
	BB_BP(body_set_transform);
	BB_BP(world_update);
	BB_BP(cast_closest);
	BB_BP(cast_closest_batch);
	BB_BP(sim_create);
	BB_BP(sim_destroy);
	BB_BP(sim_body_count);
	BB_BP(sim_settings_preset);
	BB_BP(sim_get_settings);
	BB_BP(sim_set_settings);
	BB_BP(sim_set_gravity);
	BB_BP(sim_get_gravity);
	BB_BP(body_desc_default);
	BB_BP(sim_body_create);
	BB_BP(sim_body_destroy);
	BB_BP(sim_body_get_transform);
	BB_BP(sim_body_get_transform_interpolated);
	BB_BP(sim_body_set_transform);
	BB_BP(sim_body_set_motion);
	BB_BP(sim_body_set_mass);
	BB_BP(sim_body_set_material);
	BB_BP(sim_body_set_damping);
	BB_BP(sim_body_set_gravity_scale);
	BB_BP(sim_body_set_layer);
	BB_BP(sim_body_set_sensor);
	BB_BP(sim_body_set_continuous);
	BB_BP(sim_body_set_sleeping);
	BB_BP(sim_body_set_report_contacts);
	BB_BP(sim_body_wake);
	BB_BP(sim_body_is_awake);
	BB_BP(sim_body_set_velocity);
	BB_BP(sim_body_get_velocity);
	BB_BP(sim_body_add_force);
	BB_BP(sim_body_add_torque);
	BB_BP(sim_body_add_impulse);
	BB_BP(sim_body_add_angular_impulse);
	BB_BP(sim_step);
	BB_BP(sim_contact_count);
	BB_BP(sim_contact_get);
	BB_BP(sim_contacts_clear);
	BB_BP(sim_ray_cast);
	BB_BP(sim_point_inside);
	BB_BP(sim_overlap_sphere);
	BB_BP(sim_overlap_box);
#undef BB_BP
	loaded = functions.world_create && functions.world_destroy && functions.mesh_create && functions.mesh_destroy && functions.mesh_query_box && functions.body_add_mesh && functions.body_remove
	         && functions.body_set_transform && functions.world_update && functions.cast_closest && functions.cast_closest_batch;
	return loaded ? &functions : nullptr;
}
} // namespace bb::physics
